#!/usr/bin/env bash
# vault-manifest.sh — keep MANIFEST.md and README.md counts true to reality.
#
# Usage:
#   ./scripts/vault-manifest.sh            # --check (default): report drift, exit 1
#   ./scripts/vault-manifest.sh --check    # same
#   ./scripts/vault-manifest.sh --write    # rewrite the generated sections
#
# Generated by this script:
#   · MANIFEST.md  — the block between <!-- BEGIN SKILLS --> and <!-- END SKILLS -->
#                    (total, per-category counts, one row per skill)
#   · README.md    — the "What's In Here" counts and "Total: N skills" line
#
# Everything else in both files is hand-written and never touched.
# Run --check in CI or before a push; run --write after importing or removing a skill.

set -euo pipefail

VAULT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

GREEN='\033[0;32m'
YELLOW='\033[1;33m'
CYAN='\033[0;36m'
RED='\033[0;31m'
RESET='\033[0m'

MODE="check"
for arg in "$@"; do
  case "$arg" in
    --check) MODE="check" ;;
    --write) MODE="write" ;;
    -h|--help) sed -n '2,20p' "${BASH_SOURCE[0]}" | sed 's/^# \{0,1\}//'; exit 0 ;;
    *) echo -e "${RED}✗${RESET} unknown flag: $arg" >&2; exit 1 ;;
  esac
done

python3 - "$VAULT_DIR" "$MODE" <<'PY'
import re
import sys
from collections import defaultdict
from pathlib import Path

try:
    import yaml
except ImportError:
    sys.exit("vault-manifest: PyYAML required (pip install pyyaml)")

vault, mode = Path(sys.argv[1]), sys.argv[2]
skills_dir = vault / "skills"
manifest, readme = vault / "MANIFEST.md", vault / "README.md"

# Preferred order; unknown categories are appended alphabetically.
ORDER = ["bilan", "general", "genies", "knowledge", "nerds", "forges", "platform"]

def parse_frontmatter(raw: str) -> dict:
    if not raw.startswith("---"):
        return {}
    parts = raw.split("---", 2)
    if len(parts) < 3:
        return {}
    try:
        return yaml.safe_load(parts[1]) or {}
    except yaml.YAMLError:
        return {}

def trigger(desc: str) -> str:
    desc = " ".join(desc.split())
    first = re.split(r"(?<=[.!?])\s", desc, maxsplit=1)[0]
    if len(first) > 100:
        first = first[:97].rsplit(" ", 1)[0] + "…"
    return first.replace("|", "\\|")

skills = defaultdict(list)
for path in sorted(skills_dir.glob("*/*/SKILL.md")):
    meta = parse_frontmatter(path.read_text(encoding="utf-8", errors="replace"))
    name = path.parent.name
    desc = str(meta.get("description") or "").strip()
    skills[path.parent.parent.name].append((name, trigger(desc) or name))

categories = [c for c in ORDER if c in skills] + sorted(c for c in skills if c not in ORDER)
total = sum(len(v) for v in skills.values())

lines = [f"## Skills ({total} total)", ""]
for cat in categories:
    rows = sorted(skills[cat])
    lines.append(f"### {cat}/ ({len(rows)} skills)")
    lines.append("| Skill | Trigger |")
    lines.append("|-------|---------|")
    for name, trig in rows:
        lines.append(f"| `{name}` | {trig} |")
    lines.append("")
block = "\n".join(lines).rstrip() + "\n"

text = manifest.read_text(encoding="utf-8") if manifest.exists() else ""
if "<!-- BEGIN SKILLS -->" not in text or "<!-- END SKILLS -->" not in text:
    sys.exit("vault-manifest: MANIFEST.md is missing the BEGIN/END SKILLS markers")

new_manifest = re.sub(
    r"<!-- BEGIN SKILLS -->.*?<!-- END SKILLS -->",
    lambda _: f"<!-- BEGIN SKILLS -->\n{block}<!-- END SKILLS -->",
    text, count=1, flags=re.S)

# README: counts are derived, prose is preserved.
def derive_readme(src: str) -> str:
    out = src
    for cat in categories:
        out = re.sub(
            rf"(\| `skills/{re.escape(cat)}/` \|[^\n]*\| )(\d+)( \|)",
            lambda m, n=len(skills[cat]): f"{m.group(1)}{n}{m.group(3)}", out)
    counts = {
        "prompts": len(list((vault / "prompts").glob("*.md"))),
        "registries": len(list((vault / "registries").glob("*.md"))),
        "configs": sum(1 for p in (vault / "configs").rglob("*") if p.is_file()) if (vault / "configs").exists() else 0,
        "system-prompts": len(list((vault / "system-prompts").glob("*.md"))),
        "scripts": len([p for p in (vault / "scripts").iterdir() if p.is_file()]),
    }
    for d, n in counts.items():
        out = re.sub(rf"(\| `{re.escape(d)}/` \|[^\n]*\| )(\d+)( \|)",
                     lambda m, n=n: f"{m.group(1)}{n}{m.group(3)}", out)
    out = re.sub(r"\*\*Total:\s*\d+\s*skills\*\*", f"**Total: {total} skills**", out)
    return out

readme_text = readme.read_text(encoding="utf-8") if readme.exists() else ""
new_readme = derive_readme(readme_text)

problems = []
if new_manifest != text:
    problems.append("MANIFEST.md")
if new_readme != readme_text:
    problems.append("README.md")
for cat in categories:
    if f"skills/{cat}/" not in readme_text:
        problems.append(f"README.md has no row for skills/{cat}/")

if mode == "check":
    if problems:
        print("vault-manifest: drift in: " + ", ".join(problems))
        print("  run ./scripts/vault-manifest.sh --write")
        sys.exit(1)
    print(f"vault-manifest: clean ({total} skills, {len(categories)} categories)")
    sys.exit(0)

manifest.write_text(new_manifest, encoding="utf-8")
readme.write_text(new_readme, encoding="utf-8")
print(f"vault-manifest: wrote {total} skills across {len(categories)} categories")
if problems:
    print("  updated: " + ", ".join(problems))
PY
